SELECT r.case_id, s.snapshot_role, r.entity_id, r.segment_id, COUNT(*) row_count, SUM(COALESCE(r.amount,0)) total_amount, SUM(CASE WHEN r.duplicate_group_id IS NOT NULL THEN 1 ELSE 0 END) duplicate_row_count, SUM(CASE WHEN r.included_by_filter THEN 1 ELSE 0 END) included_row_count, SUM(CASE WHEN NOT r.included_by_filter THEN 1 ELSE 0 END) excluded_row_count FROM {{PUBLIC}}.source_record r JOIN {{PUBLIC}}.source_snapshot s USING (case_id, snapshot_id) GROUP BY r.case_id, s.snapshot_role, r.entity_id, r.segment_id
